//! Same descriptor for models, human manual and Argus/diagnostic adapters.

pub const DESCRIPTOR: &str = r#"{"owner":"STUDIO-MODULE-INTEROP_LAYOUT","version":1,"operation":"open_idml(bytes, Limits, CancellationToken) -> IdmlPackage (every part kept with sha256); decode_idml / import_idml(bytes, Limits, IdMint, CancellationToken) -> IdmlImport {package, model, proposal {Folio snapshot, StudioTextStory per story, style refs, ids}, loss}; replace_content(package, ContentEdit, Limits, token) -> IdmlPackage; write_idml(package) -> bytes; export_idml(import, token) -> bytes; reflow_import(import, ParagraphShaper, ReflowOptions, token) -> ThreadReflow[] (hsk-studio-layout placement + overset span per frame chain, or a typed layout refusal); export_folio(FolioExportInput {Folio StudioDocument, StudioTextStory inputs, ExportNames}, Limits, token) -> FolioExport {IDML bytes, typed model, loss}; IdmlImport::export_names(); identify_indd(bytes) -> IndKind; import_indd(bytes, Limits, token) -> always Err; export_pdf(PdfExportInput, token) -> PdfExportOutput (native document to PDF through hsk-studio-press, see pdf_export)","operator":{"intent":"Bring an InDesign IDML package into a Studio layout document as page spreads, pages, threaded text frames and text stories without silent loss, edit story text, and write IDML back","result":"A proposal (nothing is committed) plus a typed loss list naming every part, element and attribute family that was not interpreted, approximated or dropped","recovery":"zip_invalid / unsafe_entry_name / duplicate_entry / mimetype_invalid: the file is not a safe IDML container, re-export it from InDesign; entity_denied: remove the DOCTYPE; budget_exceeded: raise the named Limits field only for a trusted file; dangling_story / thread_not_reciprocal / cyclic_thread: the frame links are corrupt; stale_source: re-decode and re-read the span; native_editability_blocked: keep the original .indd, export IDML from InDesign and import that; canceled: nothing was produced"},"model":{"container":"ZIP; mimetype first and stored with the exact IDML string; STORE and DEFLATE only; no ZIP64, encryption or multi-disk; names must be relative without .., backslash, drive colon or control characters; exact and case-folded duplicates rejected; local header must match the central directory; overlapping entry data refused; CRC-32 verified","units":"IDML geometry is points (Unit::Points, no conversion); page GeometricBounds are top left bottom right in page coordinates; page and frame ItemTransform are affine [a b c d tx ty]; frame bounds are the bounding box of the path anchors under ItemTransform, converted to the coordinates of the page with the largest overlap","folio":"one StudioPageSpread per Spread (name = page names joined), one StudioPage per Page (side from FacingPages and spine position, margins from the page MarginPreference or the document MarginPreference, bleed from DocumentPreference), one text layer with text_frame per TextFrame (columns, gutter, inset, vertical justification, first baseline, auto size from TextFramePreference), previous/next thread links rebuilt from the validated chain, one StudioTextStory per Story (paragraph and character ranges, applied styles as STYS ids that Folio reports unresolved because style definitions stay in Resources/Styles.xml, applied language as a sanitized key)","text":"story text = Content text; a Br ends the paragraph and contributes one newline; special-character processing instructions are dropped and reported","threads":"previous/next must be reciprocal and acyclic (typed errors); a link to a frame outside the supported subset ends the chain there and is reported; a second chain of the same story is not projected and is reported","reflow":"every story with a Folio frame chain is composed by hsk-studio-layout (first-fit or Knuth-Plass, one column, top-aligned fixed-size frames, left-to-right Latin); shaping is a host port (ParagraphShaper; FixedAdvanceShaper is a fixture, not shaping) because IDML names fonts and does not carry them; an RTL/CJK/vertical/complex-script story (reflow_certified false) is refused as unsupported_composition before shaping; layout refusals (multi-column, vertical justification, auto size, cap height/em box/x-height first baseline, missing_font, ...) are returned per thread and never hide other threads; overset is the first unplaced story byte through the end of the story; AscentOffset/LeadingOffset/FixedHeight first baselines are mapped to layout fixed offset inset_top + max(min, metric of the first shaped paragraph) and reported as first_baseline_mapped_to_fixed (UNVERIFIED against InDesign)","folio_export":"the Folio document is validated first; pages are placed with the spine at the origin for facing pages and at the spread centre otherwise, frames are written as rectangular paths with TextFramePreference, stories as paragraph/character ranges with Br paragraph ends; style and language references are written through ExportNames (unmapped = built-in no-style, reported); artboards, non-text layers, layer appearance, sequences, per-page bleed differences and single-sided pages in a facing document are reported; ids are minted deterministically (us1, up1, uf1, ua1); the package shape and DOMVersion 16.0 are UNVERIFIED against InDesign","groups":"text frames inside Group elements (any depth) are not decoded (group transforms are not composed) and are counted as preserved_opaque text_frame_in_group_not_decoded; the group stays verbatim; links to such frames end the chain and are reported as thread_link_outside_subset","memory":"the attributes and Properties XML of a ParagraphStyleRange / CharacterStyleRange are stored once per range and shared (Arc) by every paragraph and run it yields; the logical size of the decoded text model (shared data counted once per use, which is what export_idml writes) is charged against Limits.max_model_bytes and a package over it is refused as budget_exceeded","preservation":"every package part is kept verbatim with its sha256; unrecognised spread and designmap children, page and frame children, story head children and Properties elements are kept as verbatim XML text in the model; export_idml writes them back, replace_content/write_idml never touch them","composition":"RTL direction or language, CJK language or typography, vertical text and complex-script languages are reported as unsupported_composition on the story and reflow_certified is false: a Latin reflow must not be run on such a story (the language lists are a heuristic, UNVERIFIED for completeness)"},"loss":{"kinds":"preserved_opaque (not interpreted, kept by every write path), unsupported (not interpreted, dropped by export_idml, kept by replace_content/write_idml), approximated (frame off page, rotated transform, curved path, defaulted margins, colour mode assumed RGB, link outside subset, unknown preference value), unsupported_composition","examples":"graphic_page_item_not_interpreted, group_not_descended and text_frame_in_group_not_decoded (frames inside groups are not decoded), part_preserved_verbatim (styles, graphics, fonts, master spreads, XML structure), paragraph_range_element_not_interpreted (paragraph-level objects), inline_object_kept (character-range tables, notes and variable instances: interpreted by import_longdoc), special_character_dropped"},"limits":{"max_bytes":134217728,"max_entries":4096,"max_entry_bytes":67108864,"max_inflated_bytes":268435456,"max_ratio":100,"xml_nodes":1000000,"max_model_bytes":268435456,"folio_nodes":100000,"case_seconds":60},"safety":"roxmltree with DTDs disabled (any DOCTYPE is refused, so no entity is ever declared or expanded); no external reference, file, network or process access exists in this crate; parts must be UTF-8","cancel":"CancellationToken is checked at entry and per entry, part, element group and story; a canceled call returns canceled and no partial result","undo":"imports are proposals only; the host records an applied revision as one reversible step; replace_content returns a new package and never mutates the input","indd":"identify_indd checks the 16-byte InDesign GUID, the 8-byte type string (DOCUMENT, BOOKBOOK, LIBRARY4), the endianness byte and the version (public registry PRONOM fmt/548, fmt/1191, fmt/1192; UNVERIFIED on an InDesign-saved file, none exists on this machine); import_indd returns NativeEditabilityBlocked with the original bytes preserved and its Ok type is uninhabited: INDD is never claimed readable and an IDML package never satisfies it (STU-IO-186)","argus":{"inspect":"IdmlImport.proposal, model and loss","action":"the same functions with the same cancellation token","capture":"caller captures the source bytes, the proposal and the Observe frame under a fresh grant"},"diagnostics":"report() emits one Observe terminal outcome; no ids, part names or text are serialized by this crate","pdf_export":{"entry":"export_pdf(PdfExportInput {snapshot: folio::Snapshot, design: Option<StudioDesignRecords>, type_styles: Option<StudioTypeStyleRecords>, stories: [PdfStory {story, text, placement: layout LayoutProposal, paragraphs: [ShapedParagraph], glyphs: [[PdfGlyph]], default_fill}], fonts: [PdfFont {bytes, face_index, hyphen}], assets: PdfAssets (SVPT paths, raster tiles, SCPF profiles), options: press ExportOptions, limits: press Limits}, token) -> PdfExportOutput {bytes, receipt (press ExportReceipt, effective_* read back, conformance not_proven), loss, pages, glyphs_drawn, paths_drawn, tiles_drawn}","adapter":"pdf_glyphs_from_type(type ParagraphResult, fonts) -> [PdfGlyph] in ShapedParagraph::from_type order (font by content hash and face; refusals font_not_supplied, glyph_id_range)","writer":"hsk-studio-press PdfExport (press owns PDF serialisation; this crate owns the mapping)","order":"layer graph: outputs in order, composite inputs by input_ordinal (0 bottom); no graph outputs -> document order + loss composition_graph_absent; layers the graph does not reach -> loss layer_not_in_composition_graph","pages":"every page of every spread; media = trim + bleed (inside/outside by page side), TrimBox, BleedBox when declared","text":"layout lines, layout advances, justification word_scale on whitespace and letter gap, Type glyph ids and offsets, hyphen glyph; fonts embedded once with /W and /ToUnicode; fill = character style fill, else paragraph style fill, else default_fill","vector":"nib paths with solid fill and stroke rows of fill_style_id / stroke_style_id; profile-bound colours ICCBased, unassigned DeviceRGB (loss)","raster":"pigment ResolvedTile (validated) as 16-bit ICCBased with the tile profile, straight alpha as SMask","losses":"typed LossEntry list (tests snapshot_lowers_to_pdf, misaligned_stale_and_refused_inputs): clipping masks, blend modes PDF lacks (drawn Normal), pass-through groups below full opacity (isolated), unresolved or invalid layer masks, gradients, dashes, non-centre stroke alignment, unresolved paths/tiles/profiles/styles, fonts press refuses, layers outside page spreads or the graph","appearance":"non-identity layer or group appearance -> press transparency group (begin_group/end_group): opacity x fill_opacity, PDF-named blend modes, isolation, enabled mask -> luminosity soft mask from PdfAssets::mask; paint-row opacity/blend and text fill alpha -> /ExtGState (test folio_appearance_becomes_transparency_groups; soft-mask compositing NOT_PROVEN by the render-back device)","clip":"appearance.clipped -> clip to the base (nearest unclipped layer painted before it at the same level): vector base -> its paths (push_clip), text base -> its glyph outlines (push_clip_text, text clipping mode 7), raster base -> its tiles' alpha (alpha soft mask over a group); missing / unresolved bases -> loss clip_base_missing / clip_base_unresolved (tests folio_clipping_gradient_and_pdfx4, folio_clip_to_text_and_raster_bases)","gradient":"gradient fill rows -> press fill_path_gradient (linear -> axial type 2; radial focal circle -> start, outer circle -> end, type 3; Folio transform composed with the page mapping; ICC when all stops share a resolved profile; spread pad / repeat / reflect, stop midpoints (percent -> power-curve exponent) and stop opacity (luminosity soft mask) mapped); losses gradient_interpolation_classic, stroke_gradient_not_exported","fonts":"press embed_font: TrueType (subset) or OpenType-CFF (CID-keyed -> bare CFF CIDFontType0C subset with glyph ids kept, codes = CIDs; name-keyed -> whole OpenType FontFile3)","pdfx4":"press ExportOptions.pdfx4 writes the PDF/X-4 identification; press check_pdfx4 self-checks the implemented rules (UNVERIFIED vs ISO 15930-7; veraPDF 1.30.3 ships no PDF/X profile); PDF/X-4 stays not_proven","pdfa2b":"press ExportOptions.pdfa2b writes the PDF/A-2b identification (pdfaid, XMP extension schemas, GTS_PDFA1 intent sharing the profile); conformance becomes pdfa_2b_verapdf_passed only through ExportReceipt::with_verapdf_report with a passing veraPDF report for the same bytes, citing its sha256","errors":"PdfExportError: canceled, stale_revision, invalid_input(<check>), press ExportError codes","proof":"tests/pdf_export.rs: snapshot_lowers_to_pdf, misaligned_stale_and_refused_inputs, layer_graph_decides_the_paint_order, type_shaped_story_takes_its_fill_from_folio_styles","longdoc":{"entry":"export_pdf_with(PdfExportInput, PdfLongDoc {tables: [PdfTable {proposal: layout TableProposal, cells: PdfStory (placement = proposal.text)}], overlays: [PdfStory placed into frames it does not own]}, token): drawn right after the host frame layer's text (fills tinted by layout tint_rgb, then strokes butt/miter centred, then cell text); stale or misplaced table placements refused (stale_revision, invalid_input table_text_placement)","proof":"tests/longdoc_pdf.rs: table_exports_fills_strokes_and_repeated_header_text, placed_graphics_fit_and_clip_to_frame_shapes, sections_and_toc_export_page_labels, footnotes_and_index_export, long_document_archival_export, page_labels_and_outline_from_sections_and_toc, press_tj_runs_program_widths_and_navigation_refusals","graphics":"PdfLongDoc.graphics: [layout PlacedGraphic]: a raster layer with a graphic frame draws its pigment tiles (validated, hash-checked) through the fit transform (pixel -> content pt by content_size / pixel extent per axis) clipped to the frame shape (rectangle, inscribed ellipse, SVPT path; unresolved path -> rectangle + loss frame_shape_unresolved) in its own paint-order position; non-finite placements refused (invalid_input graphic_placement)","numbering_toc":"page labels and TOCs reach PDF as ordinary composed stories (GeneratedStory::to_story + reflow + PdfStory); PDF /PageLabels and outline bookmarks are not written (press has no page-label or outline writer: gap)","footnotes":"footnote note text is drawn as PdfLongDoc.overlays (FootnoteProposal::note_text placements in the host frames); reference markers are caller-shaped overlay stories at PlacedNote::reference; PdfLongDoc.rules strokes FootnoteProposal::rules in their frame; non-finite rules refused (invalid_input rule_placement)","conformance":"text runs use press show_glyph_run: /W = the font program hmtx widths, kerned and justified positions kept as TJ adjustments; veraPDF 1.30.3 PDF/A-2b passes the long-document and labels/outline exports (normalised report fixtures tests/fixtures/verapdf/layout-longdoc.pdfa-2b.xml, layout-labels-outline.pdfa-2b.xml, bound to pinned output sha256)","navigation":"PdfLongDoc.page_labels (page_labels_from_sections: one /PageLabels range per section start with /S D|R|r|A|a, /P = included prefix, /St = page number; styles PDF cannot express get one /P-only range per page) and PdfLongDoc.outline (outline_from_toc: bookmarks per placed TOC entry, nested by level, /XYZ at the entry's source baseline) through press set_page_labels / set_outline; unknown pages refused (invalid_input navigation_page)"}},"next":"Type-backed ParagraphShaper with IDML style-to-font resolution, text wrap obstacles, decoding frames inside groups with composed transforms, Chronicle patch write-back of edits, paragraph and character style definitions (Resources/Styles.xml), master spreads, anchored objects, index and running-text IDML mapping, linked image pixels, EPUB and PDF-X","idml_longdoc":{"entry":"import_longdoc(IdmlImport, Limits, IdMint, token) -> LongDocImport {snapshot (proposal document + one raster layer without tiles per graphic frame), records: folio StudioLongDocRecords, stories (cell / footnote / endnote stories), container_stories (IsEndnoteStory proposal stories), style_refs, ids (graphic layers, minted stories), unresolved, loss}; LongDocImport::extend_names(ExportNames); export_folio_longdoc(FolioExportInput, LongDocExportInput {records, stories}, Limits, token) -> FolioExport","import":"the decoder keeps Table / Footnote / Endnote / EndnoteRange / TextVariableInstance inside CharacterStyleRange in place (RunModel.inline, preserved_opaque inline_object_kept), so objects get host bytes by the proposal text rule; Table -> StudioTable (Header/Body/FooterRowCount row types, AutoGrow + SingleRowHeight / Minimum / MaximumHeight, SingleColumnWidth, Cell Name col:row, spans, insets, FillColor / FillTint via Resources/Graphic.xml RGB or CMYK swatches, edge strokes and priorities, VerticalJustification; one cell story per table); Footnote -> StudioFootnote + note story (number-marker PI and one separator tab dropped); Endnote@Self paired with EndnoteRange@SourceEndnote of IsEndnoteStory stories -> StudioEndnote; designmap Section -> StudioSection (check_sections), TextVariable (12 kinds) -> StudioTextVariable, ChapterNumberPreference -> chapter number; Styles.xml TOCStyle / TOCStyleEntry -> StudioTocStyle (^t -> tab; check_toc_style); Preferences FootnoteOption / EndnoteOption -> options; spread Rectangle / Oval / Polygon with Image -> StudioGraphicFrame (page by largest overlap, GraphicBounds = content size, FrameFittingOption crops / FittingOnEmptyFrame / FittingAlignment; the applied fit is the first fit_content mode reproducing the image transform within 1e-3 pt, order cleared, content_to_frame, proportionally, fill_proportionally, center_content, preserve_sizes); result re-validated by validate_document, validate_text_story and validate_longdoc_records","export":"export_folio plus: inline Table / Footnote / Endnote at the record anchors (runs split; at a paragraph end before the Br; past the end in a new last paragraph, approximated anchor_past_story_end), one IsEndnoteStory story of EndnoteRange elements, designmap Section / TextVariable / idPkg:Styles / idPkg:Graphic, Resources/Styles.xml RootTOCStyleGroup, Resources/Graphic.xml RGB swatches (Color/hskN), ChapterNumberPreference / FootnoteOption / EndnoteOption in the preferences, graphic frames as Rectangle / Oval (ug ids) with FrameFittingOption and an Image whose ItemTransform is the layout fit_content transform and GraphicBounds 0 0 w h (pixels not written; Link hsk-studio-layer:<layer id>)","round_trip":"import -> export -> import equal on every modelled field modulo minted ids, then a fixed point (same records, byte-identical package): tests/idml_longdoc.rs idml_longdoc_export_round_trip_is_stable","losses":"unsupported: nested_table_not_imported, note_in_note_or_cell_not_imported, table_too_large / table_empty / span_invalid / span_overflow / cells_overlap / check_table_grid codes (table dropped), endnote_range_missing, endnote_range_without_reference, variable_type_not_mapped, variable_text_before_after_not_imported, variable_instance_text_not_in_story, check_sections / check_toc_style / check_footnote_options codes, placed_content_not_raster, linked_pixels_not_imported, auto_fit_not_imported, graphic_frame_off_page, swatch_space_not_mapped; export: row_allow_split_not_exported, cell_character_styles_not_exported, index_not_exported, running_text_not_exported, sidenote_not_exported; approximated: cmyk_swatch_converted_without_profile, swatch_unresolved_black, number_style_not_mapped, graphic_placement_not_a_fit_mode, polygon_frame_imported_as_rectangle, frame_path_shape_exported_as_rectangle, fit_not_reproducible_exported_unfitted, chapter_numbers_collapsed_to_first, colour_profile_not_exported","hostile":"Row / Column / Cell elements counted against folio MAX_TABLE_ROWS / COLUMNS / CELLS before any grid; occupancy grid (<= MAX_TABLE_CELLS slots) refuses an invalid span, a span past the edge or an overlap at the first offending slot; spans are never clamped; no recursion into nested tables or notes; MAX_TABLES; fragments parsed with the package XML limits (tests/idml_longdoc.rs idml_longdoc_features_import_with_typed_losses, idml_longdoc_refusals_are_typed)","unverified":"InDesign parity UNVERIFIED (D5 oracle ID-05 / ID-06): Endnote@Self body reference, TOCStyle / TOCStyleEntry, TextVariable preference, FootnoteOption / EndnoteOption / ChapterNumberPreference attribute names, BreakHeaders / BreakFooters / SkipFirstHeader / SkipLastFooter / StrokeOrder / StartRow values, covered-cell elements, GraphicBounds units; names confirmed by DesignCraft crates/idml (MIT OR Apache-2.0) and Okapi issue 856 are listed in the module docs","indd":"unchanged: import_indd always refuses (NativeEditabilityBlocked, original bytes preserved)"},"epub":{"lane":"SMB-ID-PREPRESS","entry":"export_epub([EpubStory {story, text}], EpubStyles {class_of, heading_of}, EpubOptions {identifier, title, language, modified, creator, publisher, date, description, rights, subject, accessibility (nine fields), break_paragraph_style, css}, token) -> EpubOutput {bytes, chapters, loss}; inspect_epub(bytes, package ZipLimits, token) -> EpubInspection","package":"reflowable EPUB 3: mimetype first and stored, META-INF/container.xml, OEBPS/content.opf (package 3.0), nav.xhtml (epub:type toc), styles.css, one XHTML per chapter; chapters split at the break_document paragraph style; ZIP through this crate's deterministic container writer","proof":"tests/id_prepress_epub.rs; epubcheck not run: EPUB 3.3 conformance NOT_PROVEN","gaps":"fixed layout, images, cover, embedded fonts, footnotes, the remaining STU-LAY-165 export preferences"},"data_merge":{"lane":"SMB-ID-PREPRESS","entry":"parse_delimited(bytes, delimiter) / parse_json_records(bytes) -> DataSource {fields (text, @image, #qr), records}; find_placeholders / check_placeholders (<<field>>); merge_story(story, text, source, record, remove_blank_lines) -> MergedRecord {story, text, graphic_fields}; select_records(all | one | range '1-3,7'); arrange_records(records, page, margins, frame, spacing, rows_first | columns_first) -> (per_page, cells)","errors":"data_file_not_text, data_source_empty, data_source_unsupported_format, placeholder_field_missing, missing_placeholders, invalid_record_range, data_row_too_wide, budget_exceeded","proof":"tests/id_prepress_merge_place.rs","gaps":"image and QR placement, content fitting, direct-to-PDF merge, spreadsheet sources"},"pdf_place":{"lane":"SMB-ID-PREPRESS","entry":"place_pdf_page(pdf, page_index, PdfCrop art|crop|trim|bleed|media|content_visible_layers|content_all_layers, max_bytes, token) -> PlacedPdf {crop_rect, content_w, content_h, document, losses}; draw_placed_pdf(PdfExport, page, placed, transform, frame clip, token) -> losses","model":"boxes from press PageView (crop inherited, bleed/trim/art default to crop, all intersected with media); content through press read_vector_document; drawn as press paths (CMYK and gray source colours kept), clips and transparency groups; hidden optional-content layers not drawn","proof":"tests/id_prepress_merge_place.rs","gaps":"shadings, images, soft masks, dashes and rotation are typed losses; form-XObject embedding and opening a PDF as a layout document are not implemented"},"composition":{"lane":"SMB-LAYOUT-COMPOSER-WIRING","api":"import_type_styles(import, Limits, IdMint, token) -> TypeStyleImport {records: Folio StudioTypeStyleRecords (paragraph styles of the applied styles and their BasedOn ancestors, style_composition, paragraph_composition), new_styles, loss}; reflow_import_typeset(import, shaper, ReflowOptions, TypesetOptions, token)","mapped":"Composer (HL Composer -> every_line, HL Single -> single_line), Hyphenation, HyphenateWordsLongerThan, HyphenateAfterFirst, HyphenateBeforeLast, HyphenateLadderLimit, HyphenWeight, HyphenationZone, HyphenateCapitalizedWords, HyphenateLastWord, HyphenateAcrossColumns, Minimum/Desired/Maximum Word/Letter Spacing and Glyph Scaling, AutoLeading, SingleWordJustification","losses":"composer_not_mapped, composition_value_out_of_range, composition_value_invalid, composition_spacing_order, based_on_missing, based_on_cycle, style_name_replaced, styles_part_missing, style_definition_missing, root_style_settings_as_paragraph_override, paragraph_style_attributes_not_mapped","proof":"tests/idml_composition.rs, tests/d5_id_oracle.rs id03_imported_styles_compose_as_the_explicit_setup","gaps":"export of composition settings back to IDML not implemented; other style attributes (fonts, size, Justification, indents) not mapped"},"frame_autosize":{"lane":"SMB-ID-FRAME-AUTOSIZE-2","import":"TextFramePreference AutoSizingType maps to Folio auto_sizing_type (unchanged); the six STU-LAY-118 rows Folio does not store (AutoSizingReferencePoint, Use/MinimumHeightForAutoSizing, Use/MinimumWidthForAutoSizing, UseNoLineBreaksForAutoSizing; names and the values CenterPoint/true/false from the oracle corpus ID-03 exports) are compared with the readings layout auto-size lays out: Off or absent rows are not reported; any reference point is auto_sizing_reference_point_not_stored; a minimum gate true on an axis the kind sizes is auto_sizing_minimum_not_stored; UseNoLineBreaksForAutoSizing other than true (width only, height and width) or false (proportional) is auto_sizing_line_breaks_not_stored, moot for height only; other values frame_preference_value_unknown (all Approximated, element TextFramePreference)","export":"export_folio writes UseMinimumHeightForAutoSizing=false, UseMinimumWidthForAutoSizing=false and the kind's UseNoLineBreaksForAutoSizing for an auto-sizing frame (Off frames unchanged) and reports auto_sizing_reference_point_not_exported (no attested value names the fixed top/left edge)","first_baseline":"Type-shaped paragraphs (ShapedParagraph::from_type) carry OS/2 cap and x height, so imported cap_height / x_height / em_box_height frames compose; a paragraph without the metric refuses first_baseline_metric_unavailable:<kind>","parity":"InDesign behaviour UNVERIFIED (D5)","proof":"tests/idml_frame_autosize.rs"}}"#;
